module transit_card (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] l,\n    input wire [9:0] p0,\n    input wire [9:0] p1,\n    input wire [9:0] p2,\n    input wire [9:0] p3,\n    input wire [3:0] d0,\n    input wire [3:0] d1,\n    input wire [3:0] d2,\n    input wire [3:0] n,\n    input wire [3:0] away_a0,\n    input wire [3:0] away_a1,\n    input wire [3:0] away_a2,\n    input wire [3:0] away_a3,\n    input wire [3:0] away_b0,\n    input wire [3:0] away_b1,\n    input wire [3:0] away_b2,\n    input wire [3:0] away_b3,\n    input wire [4:0] t,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE = 4'd0,\n                    COMPUTE_SEGMENTS = 4'd1,\n                    DP_INIT = 4'd2,\n                    DP_OUTER_LOOP = 4'd3,\n                    DP_INNER_LOOP = 4'd4,\n                    COMPUTE_LENGTH = 4'd5,\n                    COMPUTE_COST = 4'd6,\n                    UPDATE_DP = 4'd7,\n                    DP_NEXT_INNER = 4'd8,\n                    DP_NEXT_OUTER = 4'd9,\n                    FINISH = 4'd10;\n\n    reg [3:0] state, next_state;\n    reg [4:0] m;\n    reg [4:0] seg [0:4];\n    reg [4:0] away [0:3];\n    reg [9:0] cum_dur [0:4];\n    reg [15:0] dp [0:5];\n    reg [4:0] i_reg, j_reg;\n    reg [4:0] L;\n    reg [15:0] cost_reg;\n    reg [4:0] remaining;\n    reg [3:0] level_reg;\n    reg [4:0] days_in_level;\n    reg [7:0] cycle_count;\n    localparam MAX_CYCLES = 8'd100;\n\n    // Price and duration arrays\n    wire [9:0] p_array [0:3];\n    wire [3:0] d_array [0:2];\n    assign p_array[0] = p0;\n    assign p_array[1] = p1;\n    assign p_array[2] = p2;\n    assign p_array[3] = p3;\n    assign d_array[0] = d0;\n    assign d_array[1] = d1;\n    assign d_array[2] = d2;\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            dp[0] <= 16'd0;\n            dp[1] <= 16'hFFFF;\n            dp[2] <= 16'hFFFF;\n            dp[3] <= 16'hFFFF;\n            dp[4] <= 16'hFFFF;\n            dp[5] <= 16'hFFFF;\n            cycle_count <= 8'd0;\n            for (integer k = 0; k < 5; k = k + 1) seg[k] <= 5'd0;\n            for (integer k = 0; k < 4; k = k + 1) away[k] <= 5'd0;\n            for (integer k = 0; k < 5; k = k + 1) cum_dur[k] <= 10'd0;\n        end\n        else begin\n            state <= next_state;\n            cycle_count <= cycle_count + 8'd1;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) cycle_count <= 8'd0;\n                end\n\n                COMPUTE_SEGMENTS: begin\n                    case (n)\n                        4'd0: begin\n                            m <= 5'd1;\n                            seg[0] <= t;\n                        end\n                        default: begin\n                            m <= n + 4'd1;\n                            seg[0] <= away_a0 - 4'd1;\n                            away[0] <= away_b0 - away_a0 + 4'd1;\n                            seg[1] <= away_a1 - away_b0 - 4'd1;\n                            if (n >= 4'd3) begin\n                                away[2] <= away_b2 - away_a2 + 4'd1;\n                                if (n == 4'd4) begin\n                                    away[3] <= away_b3 - away_a3 + 4'd1;\n                                    seg[4] <= t - away_b3;\n                                end else begin\n                                    seg[3] <= t - away_b2;\n                                end\n                            end else if (n == 4'd2) begin\n                                seg[2] <= t - away_b1;\n                            end\n                        end\n                    endcase\n\n                    if (l >= 4'd2) cum_dur[1] <= d0;\n                    if (l >= 4'd3) cum_dur[2] <= d0 + d1;\n                    if (l >= 4'd4) cum_dur[3] <= d0 + d1 + d2;\n                end\n\n                DP_INIT: begin\n                    dp[0] <= 16'd0;\n                    i_reg <= 5'd1;\n                end\n\n                DP_INNER_LOOP: begin\n                    j_reg <= j_reg + 5'd1;\n                end\n\n                COMPUTE_LENGTH: begin\n                    L <= 5'd0;\n                    for (integer k = j_reg; k < i_reg; k = k + 1) L <= L + seg[k] + away[k];\n                    L <= L + seg[i_reg];\n                end\n\n                COMPUTE_COST: begin\n                    if (level_reg < l - 4'd1) begin\n                        days_in_level <= (remaining > d_array[level_reg]) ? d_array[level_reg] : remaining;\n                        cost_reg <= cost_reg + days_in_level * p_array[level_reg];\n                        remaining <= remaining - days_in_level;\n                        level_reg <= level_reg + 4'd1;\n                    end\n                    else begin\n                        cost_reg <= cost_reg + remaining * p_array[level_reg];\n                    end\n                end\n\n                UPDATE_DP: begin\n                    if ((dp[j_reg] + cost_reg) < dp[i_reg]) begin\n                        dp[i_reg] <= dp[j_reg] + cost_reg;\n                    end\n                end\n\n                FINISH: begin\n                    result <= dp[m];\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = COMPUTE_SEGMENTS;\n            end\n\n            COMPUTE_SEGMENTS: next_state = DP_INIT;\n\n            DP_INIT: next_state = DP_OUTER_LOOP;\n\n            DP_OUTER_LOOP: begin\n                if (i_reg <= m) next_state = DP_INNER_LOOP;\n                else next_state = FINISH;\n            end\n\n            DP_INNER_LOOP: begin\n                if (j_reg < i_reg) next_state = COMPUTE_LENGTH;\n                else next_state = DP_NEXT_OUTER;\n            end\n\n            COMPUTE_LENGTH: begin\n                cost_reg = 16'd0;\n                remaining = L;\n                level_reg = 4'd0;\n                next_state = COMPUTE_COST;\n            end\n\n            COMPUTE_COST: begin\n                if (remaining > 5'd0 && level_reg < l && level_reg < 4'd3) begin\n                    if (remaining > d_array[level_reg]) begin\n                        next_state = COMPUTE_COST;\n                    end\n                    else if (level_reg < l-1) begin\n                        next_state = COMPUTE_COST;\n                    end\n                end\n                next_state = UPDATE_DP;\n            end\n\n            UPDATE_DP: next_state = DP_NEXT_INNER;\n\n            DP_NEXT_INNER: begin\n                next_state = (j_reg < i_reg-1) ? DP_INNER_LOOP : DP_NEXT_OUTER;\n            end\n\n            DP_NEXT_OUTER: begin\n                i_reg = i_reg + 5'd1;\n                next_state = (i_reg <= m) ? DP_OUTER_LOOP : FINISH;\n            end\n\n            FINISH: next_state = IDLE;\n\n            default: next_state = IDLE;\n        endcase\n\n        // Cycle limit safety\n        if (cycle_count >= MAX_CYCLES) next_state = FINISH;\n    end\n\nendmodule